using CreatorPay.Application.Authentication;
using CreatorPay.Application.Checkout;
using Microsoft.AspNetCore.SignalR;
namespace CreatorPay.Api.Checkout;

public static class CheckoutEndpoints
{
    public static IEndpointRouteBuilder MapCheckoutEndpoints(this IEndpointRouteBuilder e) { var auth = e.MapGroup("/api/v1/customers"); auth.MapPost("/register", (RegisterCustomerRequest r, ICheckoutService s, CancellationToken ct) => Run(() => s.RegisterCustomerAsync(r, ct), 201)); var c = e.MapGroup("/api/v1/customer").RequireAuthorization("CustomerOnly"); c.MapPost("/checkouts", (CreateCheckoutRequest r, HttpRequest h, ICurrentUserService u, ICheckoutService s, CancellationToken ct) => Run(() => s.CreateAsync(u.CustomerId!.Value, Key(h), r, ct), 201)); c.MapGet("/checkouts", (ICurrentUserService u, ICheckoutService s, CancellationToken ct) => Run(() => s.GetCustomerCheckoutsAsync(u.CustomerId!.Value, ct))); c.MapPost("/checkouts/{id:guid}/approve", async (Guid id, HttpRequest h, ICurrentUserService u, ICheckoutService s, IHubContext<CheckoutHub> hub, CancellationToken ct) => { var x = await s.ApproveAsync(u.CustomerId!.Value, id, Key(h), ct); await hub.Clients.Group($"merchant:{x.MerchantId}").SendAsync("CheckoutCompleted", x, ct); return Results.Ok(x); }); c.MapPost("/checkouts/{id:guid}/reject", (Guid id, ICurrentUserService u, ICheckoutService s, CancellationToken ct) => Run(() => s.RejectAsync(u.CustomerId!.Value, id, ct))); c.MapGet("/wallet", (ICurrentUserService u, ICheckoutService s, CancellationToken ct) => Run(() => s.GetWalletAsync(u.CustomerId!.Value, ct))); c.MapPost("/cashback-payouts", (HttpRequest h, ICurrentUserService u, ICheckoutService s, CancellationToken ct) => Run(() => s.RequestPayoutAsync(u.CustomerId!.Value, Key(h), ct), 201)); c.MapGet("/cashback-payouts", (ICurrentUserService u, ICheckoutService s, CancellationToken ct) => Run(() => s.GetPayoutsAsync(u.CustomerId, ct))); var cashier = e.MapGroup("/api/v1/cashier/checkouts").RequireAuthorization("CashierOnly"); cashier.MapPost("/present", async (PresentCheckoutRequest r, HttpRequest h, ICurrentUserService u, ICheckoutService s, IHubContext<CheckoutHub> hub, CancellationToken ct) => { var x = await s.PresentAsync(u.MerchantId!.Value, u.CashierId!.Value, Key(h), r, ct); await hub.Clients.Group($"customer:{x.CustomerId}").SendAsync("CheckoutApprovalRequired", x, ct); return Results.Ok(x); }); var a = e.MapGroup("/api/v1/admin/customer-payouts").RequireAuthorization("PlatformAdminOnly"); a.MapGet("/", (ICheckoutService s, CancellationToken ct) => Run(() => s.GetPayoutsAsync(null, ct))); a.MapPost("/{id:guid}/processing", (Guid id, ICurrentUserService u, ICheckoutService s, CancellationToken ct) => Run(() => s.MarkPayoutProcessingAsync(id, u.UserAccountId!.Value, ct))); a.MapPost("/{id:guid}/mark-paid", (Guid id, MarkCustomerPayoutPaidRequest r, HttpRequest h, ICurrentUserService u, ICheckoutService s, CancellationToken ct) => Run(() => s.MarkPayoutPaidAsync(id, u.UserAccountId!.Value, Key(h), r, ct))); a.MapPost("/{id:guid}/mark-failed", (Guid id, string reason, ICurrentUserService u, ICheckoutService s, CancellationToken ct) => Run(() => s.MarkPayoutFailedAsync(id, u.UserAccountId!.Value, reason, ct))); return e; }
    static string Key(HttpRequest r) => r.Headers["Idempotency-Key"].ToString(); static async Task<IResult> Run<T>(Func<Task<T>> f, int status = 200) { try { return Results.Json(await f(), statusCode: status); } catch (KeyNotFoundException x) { return Results.Problem(statusCode: 404, detail: x.Message); } catch (UnauthorizedAccessException x) { return Results.Problem(statusCode: 403, detail: x.Message); } catch (ArgumentException x) { return Results.Problem(statusCode: 400, detail: x.Message); } catch (InvalidOperationException x) { return Results.Problem(statusCode: 409, detail: x.Message); } }
}
